// Text for OXOS's own screens: the boot splash's caption and label (splash.cpp) and the fatal error and bug check
// screens (core/fatal.cpp). Resident, as those screens can come up after the boot-only code is freed.
#include <xk/bootscreen.h>
#include <xk/hardware.h>
#include <xk_version.h> // XK_VERSION_TEXT, generated by the Makefile

