ULONG XkTextWidth(const char *Text, ULONG Scale) {
    ULONG n = 0;
    while (Text[n])
        n++;
    return n ? n * 6 * Scale - Scale : 0;
}

void XkDrawText(ULONG *Image, ULONG Pitch, ULONG X, ULONG Y, const char *Text, ULONG Scale, ULONG Color) {
    for (; *Text; Text++, X += 6 * Scale) {
        UCHAR c = (UCHAR)*Text;
        if (c < 0x20 || c > 0x7E)
            c = '?';
        const UCHAR *rows = XkFont[c - 0x20];
        for (ULONG r = 0; r < 8; r++) {
            for (ULONG col = 0; col < 5; col++) {
                if (!(rows[r] & (0x10 >> col)))
                    continue;
                for (ULONG dy = 0; dy < Scale; dy++) {
                    ULONG *line = Image + (Y + r * Scale + dy) * Pitch + X + col * Scale;
                    for (ULONG dx = 0; dx < Scale; dx++)
                        line[dx] = Color;
                }
            }
        }
    }
}

// The OXOS version and the video encoder the kernel found (hardware/video.cpp, by its SMBus address): v0.3.16/CONEXANT
// (1.0-1.3), .../FOCUS (1.4-1.5), .../XCALIBUR (1.6); v0.3.16 alone when no encoder answered. Builds made without a
// release version say DEV.
void XkVersionLabel(char *Buffer, ULONG Size) {
    const char *encoder = AvpEncoderAddress == 0x8A   ? "CONEXANT"
                          : AvpEncoderAddress == 0xD4 ? "FOCUS"
                          : AvpEncoderAddress == 0xE0 ? "XCALIBUR"
                                                      : nullptr;
    ULONG n = 0;
    auto append = [&](const char *text) {
        for (ULONG i = 0; text[i] && n + 1 < Size; i++)
            Buffer[n++] = text[i];
    };
    append(XK_VERSION_TEXT);
    if (encoder) {
        append("/");
        append(encoder);
    }
    Buffer[n] = 0;
}
